// Requires the routes to compute, for every generated case, what the
// reference implementation computes. The cases are generated by
// test/next/conversion_cases.py into the build tree.

#include "conversion/conversion_types.h"

#include <dingo/conversion/route.h>

#include <gtest/gtest.h>

#include <cstddef>
#include <cstdint>
#include <string>

namespace dingo::next_test {

struct conversion_case {
  const char *name;
  const dingo::type_tree *stored;
  const dingo::scope_info *scope;
  const dingo::type_tree *interfaces[dingo::max_interfaces];
  std::size_t interface_count;
  dingo::request_kind kind;
  const dingo::type_tree *request;
  bool registered;
  bool found;
  bool served;
  dingo::route_step rules[dingo::max_rules_per_route];
  std::size_t rule_count;
};

extern const conversion_case conversion_cases[];
extern const std::size_t conversion_case_count;

namespace {

// The steps of a route as the forms and the addresses of the kinds.
std::string rules_of(const dingo::route_step *rules, std::size_t count) {
  std::string text;
  for (std::size_t index = 0; index < count; ++index) {
    text +=
        std::to_string(static_cast<int>(rules[index].form)) + ":" +
        std::to_string(reinterpret_cast<std::uintptr_t>(rules[index].kind)) +
        " ";
  }
  return text;
}

TEST(conversion_conformance, computes_what_the_reference_computes) {
  std::size_t failures = 0;
  for (std::size_t index = 0; index < conversion_case_count; ++index) {
    const conversion_case &expected = conversion_cases[index];
    dingo::binding_descriptor binding;
    binding.stored = *expected.stored;
    binding.leaves = dingo::named_leaves(binding.stored);
    binding.scope = *expected.scope;
    for (std::size_t i = 0; i < expected.interface_count; ++i) {
      binding.interfaces[i] = *expected.interfaces[i];
    }
    binding.interface_count = expected.interface_count;
    dingo::request_descriptor request{expected.kind, *expected.request, {}};

    bool registered = dingo::register_status(binding) ==
                      dingo::registration_status::registered;
    bool found = registered && dingo::finds(binding, request);
    bool served = false;
    std::string rules;
    if (found) {
      // The reachable types of a binding built at run time, in room that
      // doubles while it is full.
      dingo::derive_then<8>(
          binding, [&](const dingo::reachable_types &reachable_types) {
            const dingo::route_choice choice =
                dingo::select_route(binding, reachable_types, request,
                                    dingo::exposed_categories(binding));
            served = choice.reachable_type != dingo::no_reachable_type;
            if (served) {
              // The rules of the reachable type, then the wrappers the request
              // creates.
              rules =
                  rules_of(
                      reachable_types.items[choice.reachable_type].rules,
                      reachable_types.items[choice.reachable_type].rule_count) +
                  rules_of(choice.created, choice.created_count);
            }
            return 0;
          });
    }
    std::string expected_rules = rules_of(expected.rules, expected.rule_count);
    if (registered != expected.registered || found != expected.found ||
        served != expected.served || rules != expected_rules) {
      if (++failures <= 20) {
        ADD_FAILURE() << expected.name << ": registered " << registered << "/"
                      << expected.registered << " found " << found << "/"
                      << expected.found << " served " << served << "/"
                      << expected.served << " rules [" << rules << "] / ["
                      << expected_rules << "]";
      }
    }
  }
  EXPECT_EQ(failures, 0u) << "of " << conversion_case_count << " cases";
}

} // namespace
} // namespace dingo::next_test
